-- Tartós, coalescing Speed Index batch állapot. Egyetlen globális UTC-napi scope-ot használunk.
CREATE TABLE speed_index_recalculation_jobs (scope_key VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, generation BIGINT UNSIGNED NOT NULL DEFAULT 0, completed_generation BIGINT UNSIGNED NOT NULL DEFAULT 0, claimed_generation BIGINT UNSIGNED NULL, status VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'pending', worker_id VARCHAR(128) NULL, claim_token CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, claimed_at DATETIME(6) NULL, heartbeat_at DATETIME(6) NULL, last_error VARCHAR(1000) NULL, run_count BIGINT UNSIGNED NOT NULL DEFAULT 0, last_completed_at DATETIME(6) NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (scope_key), KEY idx_speed_batch_claim (status, heartbeat_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
